struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

VSOut VSMain(uint vid : SV_VertexID)
{
    VSOut o;
    o.uv = float2((vid << 1) & 2, vid & 2);
    o.pos = float4(o.uv * 2.0f - 1.0f, 0.0f, 1.0f);
    o.uv.y = 1.0f - o.uv.y;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float2 uv : TEXCOORD0;
};

float scene(float2 uv, float t)
{
    float val = 0.0f;
    float2 c1 = float2(0.35f + 0.15f * sin(t * 0.8f), 0.35f + 0.15f * cos(t * 0.6f));
    float d1 = length(uv - c1);
    val += step(d1, 0.12f);
    float2 c2 = float2(0.65f + 0.1f * cos(t), 0.55f + 0.1f * sin(t * 1.1f));
    float d2 = length(uv - c2);
    val += step(d2, 0.09f) * 0.7f;
    float2 rp = uv - float2(0.5f, 0.7f + 0.05f * sin(t * 0.5f));
    float rect = step(abs(rp.x), 0.15f) * step(abs(rp.y), 0.06f);
    val += rect * 0.5f;
    float2 c3 = float2(0.25f, 0.7f + 0.08f * cos(t * 0.9f));
    float d3 = length(uv - c3);
    val += step(d3, 0.07f) * 0.9f;
    float grid = step(0.9f, frac(uv.x * 10.0f)) + step(0.9f, frac(uv.y * 10.0f));
    val += grid * 0.2f;
    return saturate(val);
}

float4 PSMain(VSOut i) : SV_Target
{
    float t = time_sim_ms * 0.001f;
    float2 uv = i.uv;
    float lum = scene(uv, t);
    float edgeX = ddx(lum);
    float edgeY = ddy(lum);
    float edge = sqrt(edgeX * edgeX + edgeY * edgeY);
    edge = smoothstep(0.01f, 0.05f, edge);
    return float4(edge, edge, edge, 1.0f);
}
